import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 서버 전체 용량의 출처가 정해지지 않아 고정값(바이트)으로 둔다. 500GB
const TOTAL_CAPACITY_BYTES = 500 * 1024 * 1024 * 1024;

@Controller('api/v1')
export class FnSfr03803Controller {
  @Get('/system-capacities')
  async getSystemCapacity(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    return transaction(async (db) => {
      let used = NaN;
      try {
        // 가정: 사용 용량은 그룹웨어 데이터베이스 크기(바이트)로 본다
        const rows = await db.query(
          'SELECT pg_database_size(current_database()) AS "usedCapacity"',
          {},
        );
        used = Number(rows[0]?.usedCapacity);
      } catch (e) {
        used = NaN;
      }
      const total = TOTAL_CAPACITY_BYTES;
      if (!Number.isFinite(used) || !Number.isFinite(total) || total <= 0) {
        throw new ApiError(
          502,
          'SERVER_CAPACITY_FETCH_FAILED',
          '서버 용량 정보를 가져오지 못했습니다. 잠시 후 다시 시도해 주세요.',
        );
      }
      // 가정: 사용률 = 사용 용량 / 전체 용량 * 100 (소수 둘째 자리까지)
      const usageRate = Math.round((used / total) * 10000) / 100;
      return {
        totalCapacity: total,
        usedCapacity: used,
        usageRate,
      };
    });
  }
}

