import { Band, ErrorText, Num, Tiles, call, useData } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03803Page({ role, notify }: PageProps) {
  const { data, error, loading, reload } = useData<Row>(
    () => call('GET', '/system-capacities', role),
    [role],
  );

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>서버 사용 용량</h2>
        <Band>
          <button
            type="button"
            onClick={() => {
              reload();
              notify('용량 현황을 다시 조회했습니다.');
            }}
          >
            다시 조회
          </button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        {data ? (
          <Tiles
            items={[
              ['서버 전체 용량 (바이트)', <Num value={data.totalCapacity} />],
              ['서버 사용 용량 (바이트)', <Num value={data.usedCapacity} />],
              ['사용률 (%)', <Num value={data.usageRate} />],
            ]}
          />
        ) : null}
      </section>
    </div>
  );
}
